import{_ as o,o as e,c as i,a5 as p}from"./chunks/framework.DJo0M80U.js";const A=JSON.parse('{"title":"Android 原生构建排坑复盘：从 yarn android 到 Metro 跑通","description":"","frontmatter":{"title":"Android 原生构建排坑复盘：从 yarn android 到 Metro 跑通","date":"2026-05-26T00:00:00.000Z","tags":["Expo","React Native","Android","Gradle","Android SDK"],"categories":["移动开发"]},"headers":[],"relativePath":"posts/移动开发/Expo/Android 原生构建排坑复盘：从 yarn android 到 Metro 跑通.md","filePath":"posts/移动开发/Expo/Android 原生构建排坑复盘：从 yarn android 到 Metro 跑通.md","lastUpdated":1790163617000}'),a={name:"posts/移动开发/Expo/Android 原生构建排坑复盘：从 yarn android 到 Metro 跑通.md"};function r(l,d,n,t,c,s){return e(),i("div",null,[...d[0]||(d[0]=[p('<p>可以，Android 这条链路也可以按“一步一句话”回顾：</p><ol><li><p>代码完成后，先执行 <code>yarn android</code>，进入 <code>expo run:android</code> 的原生 Android 构建流程。</p></li><li><p>一开始 Expo 找不到 Android SDK，提示 <code>Failed to resolve the Android SDK path</code>。</p></li><li><p>发现本机虽然有 Android Studio，但终端没有正确识别 Android SDK。</p></li><li><p>检查 <code>~/Library/Android/sdk</code>，确认 SDK 实际目录存在。</p></li><li><p>配置 <code>ANDROID_HOME=/Users/ronnie/Library/Android/sdk</code>，让 Gradle 和 Expo 能找到 SDK。</p></li><li><p>配置 <code>platform-tools</code> 到 <code>PATH</code>，让终端可以执行 <code>adb</code>。</p></li><li><p>执行 <code>adb version</code>，确认 Android Debug Bridge 已经可用。</p></li><li><p>给项目补充 <code>android/local.properties</code>，明确写入本机 SDK 路径。</p></li><li><p>再次执行 <code>yarn android</code>，进入 Gradle 构建阶段。</p></li><li><p>构建时提示找不到 Java Runtime，说明 JDK 环境还没准备好。</p></li><li><p>安装 JDK 17，因为 React Native / Gradle 构建需要 Java 环境。</p></li><li><p>执行 <code>java -version</code>，确认 OpenJDK 17 已经可用。</p></li><li><p>执行 <code>/usr/libexec/java_home -v 17</code>，找到 JDK 17 的真实路径。</p></li><li><p>配置 <code>JAVA_HOME</code>，让 Gradle 明确使用 JDK 17。</p></li><li><p>再次执行 <code>yarn android</code>，Gradle 开始下载自身和项目依赖。</p></li><li><p>中途遇到 Maven / Kotlin 依赖下载失败，说明 Gradle 访问远程仓库网络不稳定。</p></li><li><p>检查并处理代理或 Maven 源问题，让 Gradle 能继续下载依赖。</p></li><li><p>构建继续后，项目提示缺少 Android NDK。</p></li><li><p>日志明确要求安装指定版本 <code>NDK 27.0.12077973</code>。</p></li><li><p>发现 <code>sdkmanager</code> 命令不可用，说明 Android SDK Command-line Tools 没装或没进 PATH。</p></li><li><p>在 Android Studio 的 SDK Tools 里安装 Android SDK Command-line Tools。</p></li><li><p>重新检查 <code>sdkmanager --version</code>，确认命令行工具可用。</p></li><li><p>通过 Android Studio 或 <code>sdkmanager</code> 安装项目指定的 NDK 版本。</p></li><li><p>检查 <code>$ANDROID_HOME/ndk</code>，确认存在 <code>27.0.12077973</code>。</p></li><li><p>再次执行 <code>yarn android</code>，发现还有 <code>Invalid https.proxyPort &#39;&#39;</code> 警告。</p></li><li><p>搜索代理配置，定位到 <code>android/gradle.properties</code> 里有空的 proxy 配置。</p></li><li><p>删除或修正 <code>systemProp.http.proxyPort=</code>、<code>systemProp.https.proxyPort=</code> 这些空配置。</p></li><li><p>再次执行 <code>yarn android</code>，Gradle 不再被错误代理配置干扰。</p></li><li><p>Gradle 完成 Android 原生项目编译。</p></li><li><p>Expo 调用 <code>adb</code> 把 debug App 安装到安卓设备或模拟器。</p></li><li><p>App 启动后连接 Metro，Android 开发版应用终于运行起来。</p></li></ol><p>一句话总结：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Android 这条路主要是在补齐本机原生开发环境：Android SDK、adb、JDK 17、JAVA_HOME、ANDROID_HOME、Command-line Tools、NDK，以及 Gradle 网络和代理配置。</span></span></code></pre></div><p>完整链路就是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>代码完成 → Expo run:android → Gradle → Android SDK → JDK 17 → adb → NDK → 原生编译 → 安装到设备 → 连接 Metro → Android 运行</span></span></code></pre></div>',6)])])}const D=o(a,[["render",r]]);export{A as __pageData,D as default};
